//! Embedded vector artwork, glyph outlines and design tokens (generated by
//! `build.rs`).
//!
//! Nothing here is parsed at run time. The mark is a list of filled paths,
//! already flattened to line segments in its 256-unit view box, with their
//! gradients; the glyphs are outlines in em units; the colours, the type
//! styles, the corner radius and the motion curves come from the Boswas UI
//! token file (`desktop/ui/tokens.json`). Everything is drawn at run time,
//! at the exact size of the display, by [`crate::raster`].

use crate::gfx::Rgb;
use crate::motion::Curve;

/// A closed polygon outline: `points`, split into contours that end at the
/// indices in `ends` (each contour is closed back to its first point), and
/// the bounds `[x0, y0, x1, y1]` of all the points.
#[derive(Clone, Copy, Debug)]
pub struct Outline {
    pub points: &'static [[f32; 2]],
    pub ends: &'static [u16],
    pub bounds: [f32; 4],
}

impl Outline {
    /// The contours, each as a slice of points.
    pub fn contours(&self) -> impl Iterator<Item = &'static [[f32; 2]]> + '_ {
        let points = self.points;
        let mut start = 0;
        self.ends.iter().map(move |&end| {
            let contour = &points[start..end as usize];
            start = end as usize;
            contour
        })
    }

    /// The area enclosed (non-zero rule, contours not overlapping each
    /// other), by the shoelace formula.
    pub fn area(&self) -> f32 {
        self.contours()
            .map(|c| {
                let twice: f32 = (0..c.len())
                    .map(|i| {
                        let (a, b) = (c[i], c[(i + 1) % c.len()]);
                        a[0] * b[1] - b[0] * a[1]
                    })
                    .sum();
                twice / 2.0
            })
            .sum::<f32>()
            .abs()
    }
}

/// A colour stop of a gradient.
#[derive(Clone, Copy, Debug, PartialEq)]
pub struct Stop {
    pub offset: f32,
    pub colour: Rgb,
    pub opacity: f32,
}

/// How a path of the mark is filled, in the mark's own units.
#[derive(Clone, Copy, Debug)]
pub enum Paint {
    Solid(Rgb),
    Linear { from: [f32; 2], to: [f32; 2], stops: &'static [Stop] },
    Radial { centre: [f32; 2], radius: f32, stops: &'static [Stop] },
}

/// The part of the mark a path belongs to: what the intro does with it.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Part {
    Stem,
    Bowl,
    Dot,
    /// Anything else appears with the mark as a whole.
    Other,
}

/// One filled path of the mark, back to front.
#[derive(Clone, Copy, Debug)]
pub struct Shape {
    pub part: Part,
    pub paint: Paint,
    pub opacity: f32,
    /// The same outline as the shape before it (a shading overlay): its
    /// coverage is computed once.
    pub same_outline: bool,
    pub outline: Outline,
}

/// The stem: a pill from `top` to `bottom`. Rising from its foot, the points
/// above `split` move down by up to `travel`, which leaves a disc.
#[derive(Clone, Copy, Debug, PartialEq)]
pub struct Stem {
    pub top: f32,
    pub bottom: f32,
    pub split: f32,
    pub travel: f32,
}

/// The bowl: a band round `centre`, cut open. Its points lie on the arc
/// from `start` clockwise over `span` degrees (0 is 12 o'clock).
#[derive(Clone, Copy, Debug, PartialEq)]
pub struct Bowl {
    pub centre: [f32; 2],
    pub radius: f32,
    pub start: f32,
    pub span: f32,
}

/// The dot of light in the counter.
#[derive(Clone, Copy, Debug, PartialEq)]
pub struct Dot {
    pub centre: [f32; 2],
    pub radius: f32,
}

/// The mark as vector geometry.
#[derive(Debug)]
pub struct Mark {
    /// Side of the square view box.
    pub view: f32,
    /// Bounds of everything drawn, `[x0, y0, x1, y1]`.
    pub ink: [f32; 4],
    pub shapes: &'static [Shape],
    pub stem: Option<Stem>,
    pub bowl: Option<Bowl>,
    pub dot: Option<Dot>,
}

/// One glyph: its outline in em units (y up, origin on the baseline at the
/// pen position) and its advance in em.
#[derive(Clone, Copy, Debug)]
pub struct Glyph {
    pub advance: f32,
    pub outline: Outline,
}

/// One weight of the typeface: the glyphs `first..=last`.
#[derive(Debug)]
pub struct Face {
    /// Distance from the top of a line to the baseline, in em.
    pub ascent: f32,
    /// Distance from the baseline to the bottom of a line, in em (negative).
    pub descent: f32,
    pub first: u8,
    pub last: u8,
    pub glyphs: &'static [Glyph],
    /// Pair kerning, sorted: (left, right, adjustment in em).
    pub kerning: &'static [(u8, u8, f32)],
}

impl Face {
    /// The kerning between two characters of the face, in em.
    pub fn kern(&self, left: u8, right: u8) -> f32 {
        self.kerning.binary_search_by(|&(l, r, _)| (l, r).cmp(&(left, right))).map_or(0.0, |i| self.kerning[i].2)
    }
}

/// The weights the boot screen sets text in.
#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash)]
pub enum Weight {
    Regular,
    SemiBold,
}

impl Weight {
    pub fn face(self) -> &'static Face {
        match self {
            Weight::Regular => &REGULAR,
            Weight::SemiBold => &SEMIBOLD,
        }
    }
}

/// An entry of the type ramp, in logical pixels.
#[derive(Clone, Copy, Debug, PartialEq)]
pub struct TextStyle {
    pub size: f32,
    /// Height of a line of text in this style.
    pub line: f32,
    pub weight: Weight,
}

/// What `build.rs` generated. (Long tables of coordinates, some of which
/// happen to look like well-known constants.)
#[allow(clippy::approx_constant)]
mod generated {
    use super::*;
    include!(concat!(env!("OUT_DIR"), "/assets.rs"));
}
pub use generated::*;

/// The mark as resvg renders it, premultiplied RGBA8, the whole view box at
/// [`MARK_REFERENCE_PX`] square (tests only).
#[cfg(test)]
pub static MARK_REFERENCE: &[u8] = include_bytes!(concat!(env!("OUT_DIR"), "/mark-reference.rgba"));

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn the_mark_is_three_parts_back_to_front() {
        let parts: Vec<Part> = MARK.shapes.iter().map(|s| s.part).collect();
        assert_eq!(parts, [Part::Bowl, Part::Bowl, Part::Bowl, Part::Stem, Part::Stem, Part::Dot]);
        // The shadow and the sheen of the bowl and of the stem are drawn on
        // the outline of the shape before them.
        let same: Vec<bool> = MARK.shapes.iter().map(|s| s.same_outline).collect();
        assert_eq!(same, [false, true, true, false, true, false]);
        assert_eq!(MARK.view, 256.0);
        for shape in MARK.shapes {
            assert_eq!(*shape.outline.ends.last().unwrap() as usize, shape.outline.points.len());
            // Inside the ink, to the rounding of the generated numbers.
            let (b, ink, e) = (shape.outline.bounds, MARK.ink, 1e-3);
            assert!(b[0] >= ink[0] - e && b[1] >= ink[1] - e && b[2] <= ink[2] + e && b[3] <= ink[3] + e, "{b:?}");
        }
    }

    #[test]
    fn the_geometry_of_the_parts_is_read_from_the_mark() {
        // desktop/branding/README.md: stem x 42 to 84, y 10 to 246; bowl
        // centre (128, 160), outer radius 86, cut at x = 94; dot centre
        // (134, 160), radius 18; ink x 42 to 214, y 10 to 246.
        let near = |a: f32, b: f32| (a - b).abs() < 0.05;
        assert!(
            near(MARK.ink[0], 42.0) && near(MARK.ink[1], 10.0) && near(MARK.ink[2], 214.0) && near(MARK.ink[3], 246.0)
        );
        let stem = MARK.stem.unwrap();
        assert!(near(stem.top, 10.0) && near(stem.bottom, 246.0) && near(stem.split, 128.0));
        // The straight middle of the pill: 246 - 10 less two ends of 21.
        assert!(near(stem.travel, 194.0), "{stem:?}");
        let bowl = MARK.bowl.unwrap();
        assert!(near(bowl.centre[0], 128.0) && near(bowl.centre[1], 160.0) && near(bowl.radius, 86.0), "{bowl:?}");
        // From the inner corner of the upper cut, clockwise over the top and
        // round to the inner corner of the lower cut.
        let inner = (34.0f32 / 46.0).asin().to_degrees();
        assert!((bowl.start - (360.0 - inner)).abs() < 0.5, "{bowl:?}");
        assert!((bowl.span - (180.0 + 2.0 * inner)).abs() < 1.0, "{bowl:?}");
        let dot = MARK.dot.unwrap();
        assert!(near(dot.centre[0], 134.0) && near(dot.centre[1], 160.0) && near(dot.radius, 18.0), "{dot:?}");
    }

    #[test]
    fn curves_are_flattened_finely() {
        // The dot is a circle of radius 18: every segment of its outline is
        // short, and its area is the circle's to a fraction of a percent.
        let dot = MARK.shapes.iter().find(|s| s.part == Part::Dot).unwrap();
        let area = dot.outline.area();
        let circle = std::f32::consts::PI * 18.0 * 18.0;
        assert!((area - circle).abs() < circle * 0.003, "{area} vs {circle}");
        assert!(dot.outline.points.len() > 60, "{} points", dot.outline.points.len());
    }

    #[test]
    fn the_glyph_outlines_are_consistent() {
        for face in [&REGULAR, &SEMIBOLD] {
            assert_eq!(face.glyphs.len(), (face.last - face.first + 1) as usize);
            assert!(face.ascent > 0.5 && face.ascent < 1.3 && face.descent < 0.0 && face.descent > -0.5);
            for (i, g) in face.glyphs.iter().enumerate() {
                assert!(g.advance > 0.0, "glyph {i}");
                let ends = g.outline.ends;
                assert!(ends.windows(2).all(|w| w[0] < w[1]));
                assert_eq!(ends.last().map_or(0, |&e| e as usize), g.outline.points.len());
            }
            // The space has no outline; letters do.
            assert!(face.glyphs[0].outline.points.is_empty());
            assert!(face.glyphs[(b'B' - face.first) as usize].outline.area() > 0.1);
            assert!(face.kerning.windows(2).all(|w| (w[0].0, w[0].1) < (w[1].0, w[1].1)), "sorted");
        }
        assert!(TYPEFACE == "Inter" || TYPEFACE == "Orbitron");
        if TYPEFACE == "Inter" {
            // Inter kerns "T" and "o" together, and "To" is narrower than "T" plus "o".
            assert!(REGULAR.kern(b'T', b'o') < -0.02, "{}", REGULAR.kern(b'T', b'o'));
            assert_eq!(REGULAR.kern(b'l', b'l'), 0.0);
        }
    }

    #[test]
    fn the_semibold_face_is_heavier() {
        // The same letters cover more in the heavier weight.
        let ink = |face: &Face| {
            "Unlock".bytes().map(|ch| face.glyphs[(ch - face.first) as usize].outline.area()).sum::<f32>()
        };
        assert!(ink(&SEMIBOLD) > ink(&REGULAR) * 1.08, "{} vs {}", ink(&SEMIBOLD), ink(&REGULAR));
    }

    #[test]
    fn tokens_come_from_the_token_file() {
        // desktop/ui/tokens.json: neutral.950, iris.400 and the dark theme.
        assert_eq!(BACKGROUND, Rgb::new(0x18, 0x17, 0x1C));
        assert_eq!(ACCENT, Rgb::new(0x9B, 0x8A, 0xFF));
        assert_eq!(TEXT, Rgb::new(255, 255, 255));
        assert_eq!(DANGER, Rgb::new(0xFF, 0x77, 0x88));
        assert_eq!(WARNING, Rgb::new(0xFF, 0xC2, 0x4F));
        // The bloom of the boot menu (azure.500, iris.500) and the sun of the dot.
        assert_eq!(BLOOM_AZURE, Rgb::new(0x2F, 0x7F, 0xF0));
        assert_eq!(BLOOM_IRIS, Rgb::new(0x7C, 0x5C, 0xFF));
        assert_eq!(GLOW, Rgb::new(0xFF, 0xC2, 0x4F));
        // A control: a subtle white fill and a slightly stronger outline.
        assert_eq!(CONTROL_LAYER, Rgb::new(255, 255, 255));
        assert_eq!((FILL_CONTROL, STROKE_CONTROL), (0.06, 0.07));
        assert_eq!(RADIUS_CONTROL, 4.0);
        assert_eq!(CAPTION, TextStyle { size: 12.0, line: 16.0, weight: Weight::Regular });
        assert_eq!(BODY, TextStyle { size: 14.0, line: 20.0, weight: Weight::Regular });
        assert_eq!(BODY_LARGE, TextStyle { size: 16.0, line: 22.0, weight: Weight::Regular });
        assert_eq!(SUBTITLE, TextStyle { size: 20.0, line: 28.0, weight: Weight::SemiBold });
        // Motion: the durations and the curves of Boswas UI.
        assert_eq!((MOTION_FAST, MOTION_NORMAL, MOTION_SLOW), (0.15, 0.2, 0.25));
        assert_eq!(DECELERATE, Curve([0.1, 0.9, 0.2, 1.0]));
        assert_eq!(ACCELERATE, Curve([0.7, 0.0, 1.0, 0.5]));
        assert_eq!(STANDARD, Curve([0.8, 0.0, 0.2, 1.0]));
    }
}
